using System.Linq;
using Maple2.PacketLib.Tools;
using Ms2.Net.Packets;
using NUnit.Framework;

namespace Ms2.Net.Tests;

/// <summary>Real OnItemInventory mode 6 (Load) payloads captured from a local test server, one per inventory tab; the character name inside is replaced by AAAAA.</summary>
public class ItemInventoryCaptureTests {
    const string Load1 = "";
    const string Load2 = "";
    const string Load3 = "";

    [TestCase(Load1, 0)] [TestCase(Load2, 1)] [TestCase(Load3, 2)]
    public void CapturedLoadConsumesEveryByte(string hex, int which) {
        var expected = new (int Id, int Slot)[][] {
            new (int, int)[] { (40100036, 0), (40100035, 1) },
            new (int, int)[] { (30000225, 0) },
            new (int, int)[] { (20000028, 0) },
        }[which];
        var r = new ByteReader(System.Convert.FromHexString(hex));
        var m = (ItemMessage.Load) ItemMessage.Read(r, _ => null);
        Assert.That(r.Available, Is.EqualTo(0));
        Assert.That(m.Items.Select(i => (i.Id, (int) i.InventorySlot)).ToArray(), Is.EqualTo(expected));
    }
}
